import {clone,id,newFrame,validateProject} from './model.js';
export const TASK_STATES=['todo','in-progress','ready'];
export const POSE_BRIEFS=[
 {id:'vertical-up',title:'Straight-up jump',category:'jump',priority:'high',tags:['vertical','up','airborne'],instructions:'Create a distinct straight-up airborne pose. Keep the body compact and legs beneath him; avoid the diagonal forward-reaching silhouette. Preserve the intended facing on a vertical jump. Start with one missing airborne frame, using existing takeoff and landing frames as onion references.'},
 {id:'vertical-down',title:'Straight-down drop',category:'jump',priority:'high',tags:['vertical','down','airborne'],instructions:'Create a distinct straight-down airborne pose with the feet prepared beneath the body. Preserve facing rather than implying a sideways leap or backwards motion. Start with one missing airborne frame; compare against existing descent preparation and landing crouch.'},
 {id:'look-down',title:'Look down from a perch',category:'idle',priority:'high',tags:['look-down','card-edge'],instructions:'Lower the head to inspect a card or landing below. Keep the planted paw cells fixed and allow the body/tail to overhang. Use the sitting/perch frames as references.'},
 {id:'horizontal-refine',title:'Refine horizontal leap',category:'jump',priority:'normal',tags:['horizontal','airborne'],instructions:'Refine the approved AI horizontal flight pose. Keep a level back, forward head, trailing tail and gathered legs. Human pixel edits to the AI source make a mixed-origin frame; retain its lineage. No planted contact anchor while airborne.'},
 {id:'walk-head',title:'Refine independent walk heads',category:'walk',priority:'normal',tags:['walk','head-bob'],instructions:'Review the high/low head combinations. Improve the head/neck seam if needed while leaving leg frames and every planted paw marker unchanged. Compare original and half-time head bobbing at the same walking speed.'},
 {id:'sitting-glance',title:'Sitting head glance',category:'idle',priority:'later',tags:['sit','look'],instructions:'Explore a small head turn toward a nearby object without flipping the whole body. Audit the existing turn/idle catalogue before drawing new pixels; keep bearing paws in their source cells.'}
];
const requireQueue=(ok,message)=>{if(!ok)throw Error(message);};
export function ensureQueue(project){project.projectId ||= id();if(!project.workQueue)project.workQueue={version:1,repository:'Stick-Pet-Card',selectedId:'vertical-up',tasks:clone(POSE_BRIEFS).map(t=>({...t,status:'todo',frameIds:[],notes:'',outputs:[]}))};return project.workQueue;}
export function validateQueue(project){
 if(project.projectId!==undefined)requireQueue(typeof project.projectId==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(project.projectId),'Invalid saved project ID.');
 if(project.workQueue===undefined)return project;
 const q=project.workQueue;requireQueue(q?.version===1&&q.repository==='Stick-Pet-Card'&&Array.isArray(q.tasks)&&q.tasks.length<=64,'Invalid pose queue.');const ids=new Set();
 for(const t of q.tasks){requireQueue(typeof t.id==='string'&&t.id.length>0&&t.id.length<=120&&!ids.has(t.id),'Invalid queue task ID.');ids.add(t.id);requireQueue(typeof t.title==='string'&&t.title.trim().length>0&&t.title.length<=120&&typeof t.instructions==='string'&&t.instructions.length<=3000,'Task needs a title and bounded instructions.');requireQueue(['high','normal','later'].includes(t.priority)&&TASK_STATES.includes(t.status),'Invalid task status or priority.');requireQueue(['idle','walk','jump','interaction','care','transition','other'].includes(t.category)&&Array.isArray(t.tags)&&t.tags.length<=20&&t.tags.every(s=>typeof s==='string'&&s.length<=40),'Invalid task labels.');requireQueue(Array.isArray(t.frameIds)&&t.frameIds.length<=96&&new Set(t.frameIds).size===t.frameIds.length&&t.frameIds.every(s=>typeof s==='string'),'Invalid linked frames.');requireQueue(typeof t.notes==='string'&&t.notes.length<=2000&&Array.isArray(t.outputs)&&t.outputs.length<=12,'Invalid task notes or outputs.');for(const o of t.outputs){requireQueue(typeof o.id==='string'&&typeof o.savedAt==='string'&&typeof o.notes==='string'&&o.notes.length<=2000&&Array.isArray(o.frames)&&o.frames.length>0,'Invalid saved pose output.');validateProject({schemaVersion:1,width:24,height:24,name:t.title,frames:o.frames});}if(t.status==='ready')requireQueue(t.outputs.length>0,'Ready tasks need a saved output.');}
 return project;
}
export function queueTask(project,taskId){const t=ensureQueue(project).tasks.find(t=>t.id===taskId);requireQueue(t,'Pose task not found.');return t;}
export function addPoseTask(project,{title,instructions='',priority='normal',category='other',tags=[]}){const task={id:id(),title:title.trim(),instructions,priority,category,tags,status:'todo',frameIds:[],notes:'',outputs:[]};ensureQueue(project).tasks.push(task);validateQueue(project);return task;}
export function linkTaskFrame(project,taskId,frameId){const t=queueTask(project,taskId);requireQueue(project.frames.some(f=>f.id===frameId),'Frame not found.');if(!t.frameIds.includes(frameId))t.frameIds.push(frameId);t.status='in-progress';return t;}
export function startTaskFrame(project,taskId,actor='human'){requireQueue(actor==='human','Switch to Human authoring to start this human pose task.');requireQueue(project.frames.length<96,'Maximum 96 frames.');const t=queueTask(project,taskId),f=newFrame(t.title+' · draft',undefined,'human');f.metadata={category:t.category,tags:[...t.tags],description:t.instructions};project.frames.push(f);linkTaskFrame(project,taskId,f.id);return f;}
export function saveTaskOutput(project,taskId,notes='',actor='human'){
 requireQueue(actor==='human','Only a human session can mark an output ready for Codex.');const t=queueTask(project,taskId);requireQueue(t.outputs.length<12,'This task has 12 saved versions. Download the project before starting another task.');requireQueue(typeof notes==='string'&&notes.length<=2000,'Notes are limited to 2000 characters.');
 const frames=t.frameIds.map(fid=>project.frames.find(f=>f.id===fid));requireQueue(frames.length>0&&frames.every(Boolean),'Link existing frames before saving.');requireQueue(frames.every(f=>f.rows.some(row=>/[^.]/.test(row))),'Draw each linked frame before marking it ready.');const output={id:id(),savedAt:new Date().toISOString(),notes,frames:clone(frames)};t.outputs.push(output);t.notes=notes;t.status='ready';return output;
}
export function savedOutput(project,taskId,outputId){const t=queueTask(project,taskId),o=outputId?t.outputs.find(o=>o.id===outputId):t.outputs.at(-1);requireQueue(o,'No saved output for this task.');return clone({projectId:project.projectId,repository:'Stick-Pet-Card',task:{id:t.id,title:t.title,instructions:t.instructions},output:o});}
export function outputMatchesFrames(project,task){const o=task.outputs.at(-1);return !!o&&JSON.stringify(o.frames)===JSON.stringify(task.frameIds.map(fid=>project.frames.find(f=>f.id===fid)));}
export function restoreTaskOutput(project,taskId){const t=queueTask(project,taskId),o=savedOutput(project,taskId).output;requireQueue(project.frames.length+o.frames.length<=96,'Not enough frame slots to restore a copy.');const frames=o.frames.map(f=>({...clone(f),id:id(),parentId:f.id,locked:false,review:'candidate'}));project.frames.push(...frames);t.frameIds=frames.map(f=>f.id);t.status='in-progress';return frames[0];}
